import sys

def numberOfEnclaves(grid):
    if not grid or not grid[0]:
        return 0

    n = len(grid)
    m = len(grid[0])

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(r, c):
        if r < 0 or r >= n or c < 0 or c >= m or grid[r][c] == 0:
            return

        grid[r][c] = 0  # Mark as visited by setting to 0 (sea)

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            dfs(nr, nc)

    # Start DFS from all land cells on the boundary
    for i in range(n):
        if grid[i][0] == 1:
            dfs(i, 0)
        if grid[i][m-1] == 1:
            dfs(i, m-1)

    for j in range(m):
        if grid[0][j] == 1:
            dfs(0, j)
        if grid[n-1][j] == 1:
            dfs(n-1, j)

    # Count remaining land cells
    count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                count += 1

    return count

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    iterator = iter(data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))

        grid = []
        for _ in range(n):
            row = []
            for _ in range(m):
                row.append(int(next(iterator)))
            grid.append(row)

        result = numberOfEnclaves(grid)
        print(result)
    except StopIteration:
        pass

if __name__ == "__main__":
    main()
